setup_code:
colors = pl.DataFrame(
    {
        "name": ["black", "yellow", "blue"],
        "code": [b"\x00\x00\x00", b"\xff\xff\x00", b"\x00\x00\xff"],
        "lit": [b"\x00", b"\xff\x00", b"\xff\xff"],
    }
)
inputs = {"colors": colors}

reference_solution:
def solve(colors: pl.DataFrame) -> pl.DataFrame:
    return (
        colors.select(
            "name",
            pl.col("code").bin.contains(b"\xff").alias("contains_with_lit"),
            pl.col("code").bin.contains(pl.col("lit")).alias("contains_with_expr"),
        )
    )

solver_code:
import polars as pl

def solve(colors: pl.DataFrame) -> pl.DataFrame:
    return colors.select(
        "name",
        contains_with_lit=pl.col("code").bin.contains(b"\xff"),
        contains_with_expr=pl.col("code").bin.contains(pl.col("lit"))
    )

setup_code:
import polars as pl
df = pl.DataFrame(
    {
        "col1": [0.5, 1, 1.5, 2, 2.5],
        "col2": [1, None, 3, None, 5],
    },
)
inputs = {"df": df}

reference_solution:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    fill_literal_df = df.with_columns(
        pl.col("col2").fill_null(3),
    )
    return fill_literal_df

solver_code:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.with_columns(
        pl.col("col2").fill_null(3)
    )

setup_code:
df = pl.DataFrame(
    {"s": [["a", "b"], ["x", "y"]], "separator": ["*", "_"]},
    schema={
        "s": pl.Array(pl.String, 2),
        "separator": pl.String,
    },
)
inputs = {"df": df}

solver_code:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.with_columns(
        pl.col("s").arr.join(pl.col("separator"), ignore_nulls=True).alias("join")
    )

setup_code:
from datetime import date
df = pl.DataFrame(
    {
        "date": [date(2024, 4, 1), date(2025, 3, 16)],
        "new_day": [10, 15],
    }
)
inputs = {"df": df}

solver_code:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.with_columns(
        pl.col("date").dt.replace(day=pl.col("new_day")).alias("replaced")
    )

def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.select(
        pl.col("values").str.extract_many(pl.col("patterns"))
    )

