setup_code:
lf = pl.LazyFrame(
    {
        "a": [1, 2, None, 4],
        "b": [0.5, 4, None, 13],
    }
)
inputs = {"lf": lf}

solver_code:
def solve(lf: pl.LazyFrame) -> pl.DataFrame:
    return (
        lf
        .with_columns(
            a=pl.col("a").fill_null(99),
            b=pl.col("b").fill_null(99.0)
        )
        .select("a", "b")
        .collect()
    )

setup_code:
df = pl.DataFrame(
    {
        "foo": [1, 2, 3, None, 4, None, 0],
        "bar": [6, 7, 8, None, None, 9, 0],
        "ham": ["a", "b", "c", None, "d", "e", "f"],
    }
)
inputs = {"df": df}

reference_solution:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    new = df.with_columns(
        nfc=pl.col("text").str.normalize("NFC"),
        nfkc=pl.col("text").str.normalize("NFKC"),
    )
    return new

