setup_code:
from datetime import datetime
df = pl.DataFrame(
    {
        "date": pl.datetime_range(
            datetime(2020, 3, 1),
            datetime(2020, 5, 1),
            "1mo",
            time_zone="UTC",
            eager=True,
        ),
    }
)
inputs = {"df": df}

reference_solution:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    return (
        df.select(
            [
                pl.col("date"),
                pl.col("date")
                .dt.convert_time_zone(time_zone="Europe/London")
                .alias("London"),
            ]
        )
    )

solver_code:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.with_columns(
        London=pl.col("date").dt.convert_time_zone("Europe/London")
    )

def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.select(
        foo=pl.col("foo").max(),
        bar=pl.col("bar").max(),
        ham=pl.col("ham").last()
    )

setup_code:
from datetime import datetime
df = pl.DataFrame(
    {
        "dates": pl.datetime_range(
            datetime(2000, 1, 15, 2),
            datetime(2000, 12, 15, 2),
            "1mo",
            eager=True,
        )
    }
)
inputs = {"df": df}

solver_code:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.select(
        dates=pl.col("dates").dt.month_start()
    )

def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.with_columns(
        min=pl.min_horizontal("a", "b")
    ).select(["a", "b", "c", "min"])
